import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Dedup for RGW Scalable Object Deduplication","description":"","frontmatter":{"title":"Ceph Dedup for RGW Scalable Object Deduplication","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["RGW","对象存储","去重","性能优化","存储优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Dedup_for_RGW_Scalable_Object_Deduplication.md","filePath":"posts/2026/Ceph_Dedup_for_RGW_Scalable_Object_Deduplication.md","lastUpdated":null}'),s={name:"posts/2026/Ceph_Dedup_for_RGW_Scalable_Object_Deduplication.md"};function r(n,a,o,h,d,p){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 Gabriel 主讲，介绍了 RGW full object deduplication（全对象去重）功能的设计与实现。该功能计划在 Ceph 9.2 版本中以 CLI 形式发布，并在 Squid（umbrella）版本中实现完整生命周期集成。</p><h2 id="为什么需要对象去重" tabindex="-1">为什么需要对象去重 <a class="header-anchor" href="#为什么需要对象去重" aria-label="Permalink to &quot;为什么需要对象去重&quot;">​</a></h2><p>对象存储中积累冗余数据的场景非常普遍：</p><ul><li><strong>备份与数据恢复</strong>：多次备份产生相同内容的副本</li><li><strong>CI/CD 流水线</strong>：构建产物跨流水线重复存储</li><li><strong>数据湖注入</strong>：相同数据集被多次导入</li><li><strong>对象版本控制（versioning）</strong>：多个版本可能包含完全相同的数据</li><li><strong>跨租户重复（cross-tenant duplication）</strong>：不同租户上传了相同数据但彼此不知情</li></ul><p>这些问题直接导致存储池容量膨胀、recovery 和 rebalance 变慢、以及更高的存储成本。</p><h2 id="当前已支持的功能" tabindex="-1">当前已支持的功能 <a class="header-anchor" href="#当前已支持的功能" aria-label="Permalink to &quot;当前已支持的功能&quot;">​</a></h2><ul><li><strong>对象版本去重</strong>：不同版本的对象各自作为独立实体参与去重，版本 A 和版本 B 若内容相同可被去重</li><li><strong>跨租户去重（multi-tenant dedup）</strong>：不同租户的相同数据可以被去重</li><li><strong>压缩对象去重</strong>：PR 正在 review 中，预计 9.2 合入 main 分支</li></ul><h2 id="不支持的场景" tabindex="-1">不支持的场景 <a class="header-anchor" href="#不支持的场景" aria-label="Permalink to &quot;不支持的场景&quot;">​</a></h2><ul><li>跨 zone、跨 pool、跨 storage class 的去重（原因：不同 storage class 代表不同冷热层级，无法决定保留哪一份）</li><li>加密对象去重（需要对 key 生命周期管理机制进行改动，目前待审批）</li></ul><h2 id="两种运行模式" tabindex="-1">两种运行模式 <a class="header-anchor" href="#两种运行模式" aria-label="Permalink to &quot;两种运行模式&quot;">​</a></h2><h3 id="estimate-模式-零风险" tabindex="-1">Estimate 模式（零风险） <a class="header-anchor" href="#estimate-模式-零风险" aria-label="Permalink to &quot;Estimate 模式（零风险）&quot;">​</a></h3><ul><li>仅访问 bucket index，不读取实际数据</li><li>统计重复数据估算值，告知用户潜在的去重收益</li><li>速度极快，约 <strong>10 万对象/秒</strong>（per RGW 实例），不影响数据 I/O</li><li>即使数据存储在 HDD 上也几乎没有性能影响</li></ul><h3 id="execute-模式-实际去重执行" tabindex="-1">Execute 模式（实际去重执行） <a class="header-anchor" href="#execute-模式-实际去重执行" aria-label="Permalink to &quot;Execute 模式（实际去重执行）&quot;">​</a></h3><p>完整执行去重，分四个阶段：</p><ol><li><strong>Bucket index 扫描（Phase 1）</strong></li><li><strong>MD5 哈希表构建（Phase 2）</strong></li><li><strong>候选对象验证（Phase 3）</strong></li><li><strong>实际去重执行（Phase 4）</strong></li></ol><h2 id="cli-与-rest-api" tabindex="-1">CLI 与 REST API <a class="header-anchor" href="#cli-与-rest-api" aria-label="Permalink to &quot;CLI 与 REST API&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CLI 操作</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">radosgw-admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dedup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [estimate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pause</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resume</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">abort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">statistics</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">throttle]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># REST API</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/admin/dedup?op</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=[estimate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>支持操作：estimate、execute、pause、resume、abort、statistics、throttle（节流控制）</p><p>统计信息每 3 秒更新一次，可实时查看进度。未来计划在 9.2/Squid 版本中集成到 Dashboard。</p><h2 id="节流控制-throttling" tabindex="-1">节流控制（Throttling） <a class="header-anchor" href="#节流控制-throttling" aria-label="Permalink to &quot;节流控制（Throttling）&quot;">​</a></h2><p>当前支持两个维度的节流：</p><ol><li><strong>Bucket index 读取速率</strong>：每次读取 1,000 条索引项，默认约 50-100 次/秒（即 5 万～10 万条/秒）</li><li><strong>Metadata 访问操作速率</strong>：控制属性读取频率</li></ol><p>第三个维度（实际数据读取速率）正在开发中。</p><h2 id="bucket-过滤-bucket-filtering" tabindex="-1">Bucket 过滤（Bucket Filtering） <a class="header-anchor" href="#bucket-过滤-bucket-filtering" aria-label="Permalink to &quot;Bucket 过滤（Bucket Filtering）&quot;">​</a></h2><p>支持 allow/deny list 机制，可以通过文件传入 bucket 名称列表：</p><ul><li><strong>Allow list</strong>：只对指定 bucket 执行去重</li><li><strong>Deny list</strong>：跳过指定 bucket（适合跳过繁忙/关键业务 bucket 或已损坏的 bucket）</li></ul><p>Storage class 同样支持 allow/deny 过滤，例如可以跳过 Glacier 等冷存储类型。</p><h2 id="架构设计详解" tabindex="-1">架构设计详解 <a class="header-anchor" href="#架构设计详解" aria-label="Permalink to &quot;架构设计详解&quot;">​</a></h2><h3 id="server-side-copy-基础" tabindex="-1">Server-side Copy 基础 <a class="header-anchor" href="#server-side-copy-基础" aria-label="Permalink to &quot;Server-side Copy 基础&quot;">​</a></h3><p>RGW 对象由 <strong>head object</strong>（元数据：S3 身份、用户属性、RGW 内部属性）和 <strong>tail object</strong>（实际数据，按 4MB 分片分布到多个 OSD）组成。</p><p>Head object 因包含不同名称和属性无法共享；tail object 可通过引用计数（ref count）实现共享，这正是 server-side copy 的实现基础。</p><p><strong>小对象 inline 优化的改动</strong>：为了支持小对象（&lt;4MB）的全量去重，9.2 引入了一个变更：去重前先将 head object 中 inline 的数据移到独立的 tail object，使得 head 变为空，tail 完全共享。</p><h3 id="双层-sharding-架构" tabindex="-1">双层 Sharding 架构 <a class="header-anchor" href="#双层-sharding-架构" aria-label="Permalink to &quot;双层 Sharding 架构&quot;">​</a></h3><p><strong>第一层：Bucket index sharding</strong></p><ul><li>每个 RGW 实例负责一组 bucket index shard，通过 compare-and-swap 竞争 token</li><li>线性扩展：N 个 RGW 约带来 N 倍加速</li></ul><p><strong>第二层：MD5 空间 sharding</strong></p><ul><li>将 MD5 空间划分为最多 255 个分区（partition）</li><li>利用模运算（modular arithmetic）保证相同 MD5 的对象总在同一分区内</li><li>核心优势：大幅降低内存占用（1 万亿对象仅需 32MB 而非 32TB）</li><li>每个 MD5 分区使用 2MB buffer 写入磁盘，顺序 I/O 开销几乎可忽略不计</li></ul><h3 id="四阶段执行流程" tabindex="-1">四阶段执行流程 <a class="header-anchor" href="#四阶段执行流程" aria-label="Permalink to &quot;四阶段执行流程&quot;">​</a></h3><p><strong>Phase 1 — Bucket Index 扫描</strong></p><p>无序（unordered）扫描各 shard，提取：MD5（ETag）、对象大小、分片数（multipart parts）、storage class、版本实例 ID、对象名。数据按 MD5 分区写入磁盘 slab 对象，建议使用 erasure coding 存储这些临时 slab。</p><p><strong>Phase 2 — 哈希表构建</strong></p><p>从磁盘 slab 读取数据，构建 open hash table（固定 32 字节 key = MD5 + size + parts count，8 字节 value = 磁盘位置指针）。Estimate 模式在此阶段结束，输出汇总对象。</p><p><strong>Phase 3 — 候选对象验证</strong></p><ul><li>清除哈希表中的单例（只出现一次的对象）</li><li>对剩余候选对象读取属性（attribute）和完整数据</li><li>跳过条件：加密对象（暂不支持）、被标记跳过的压缩对象、自快照时间点起已变更的对象</li><li>计算 <strong>BLAKE3 哈希</strong>（256 bit，密码学安全，速度约是 SHA-256 的 7 倍），用于最终确认对象内容完全一致</li><li>BLAKE3 哈希存储在对象属性中，供增量去重复用</li></ul><p><strong>Phase 4 — 执行去重</strong></p><ul><li>比较 BLAKE3 哈希确认一致后执行去重</li><li>对 source 对象递增 ref count（如有 inline data 先拆分到 tail）</li><li>将 BLAKE3 哈希存入 source 对象属性（供后续增量去重复用）</li><li>对 target 对象执行<strong>原子验证覆写（atomic verify-overwrite）</strong>：校验 ETag、hash、size 不变后替换 manifest 为指向 source tail 的新 manifest</li><li>删除 target 的 tail objects（<strong>同步删除</strong>，不进入 GC 队列，避免积压）</li><li>任何步骤失败均执行 rollback，跳过该对象，不影响系统稳定性</li></ul><h2 id="增量去重-incremental-dedup" tabindex="-1">增量去重（Incremental Dedup） <a class="header-anchor" href="#增量去重-incremental-dedup" aria-label="Permalink to &quot;增量去重（Incremental Dedup）&quot;">​</a></h2><ul><li>已参与去重的对象在属性中打上标记，下次扫描时自动跳过</li><li>BLAKE3 哈希持久化存储，再次去重时无需重新读取和计算数据</li><li>Source 对象保持稳定，所有副本始终指向同一个原始 source</li></ul><h2 id="为什么选择全对象去重而非-chunk-level-dedup" tabindex="-1">为什么选择全对象去重而非 chunk-level dedup <a class="header-anchor" href="#为什么选择全对象去重而非-chunk-level-dedup" aria-label="Permalink to &quot;为什么选择全对象去重而非 chunk-level dedup&quot;">​</a></h2><ol><li><strong>加密问题</strong>：现代 RGW/AWS 部署中 server-side encryption 已成主流。Chunk-level dedup 需要对所有数据解密再计算哈希，代价极高；而全对象 dedup 利用 ETag（明文数据的 MD5）作为初筛，只对极少数候选对象才读取和解密数据</li><li><strong>压缩冲突</strong>：4MB 块压缩在去重场景下难以处理，块边界与去重边界产生冲突</li><li><strong>性能效率</strong>：chunk-level 需要对全量数据计算哈希；全对象 dedup 利用 ETag 预筛，只有极少数对象（约 1/500 万为误判）需要支付完整读取代价</li></ol><h2 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>状态</th><th>特性</th></tr></thead><tbody><tr><td>Ceph 9.0</td><td>已发布</td><td>基础 estimate 模式（存在计算局限，建议不要单独使用）</td></tr><tr><td>Ceph 9.2</td><td>开发中</td><td>完整去重（CLI + REST API）、压缩对象支持（PR pending review）</td></tr><tr><td>Squid（Umbrella）</td><td>规划中</td><td>生命周期集成（定时自动去重服务）、telemetry、Dashboard 集成</td></tr></tbody></table><h2 id="社区呼吁" tabindex="-1">社区呼吁 <a class="header-anchor" href="#社区呼吁" aria-label="Permalink to &quot;社区呼吁&quot;">​</a></h2><p>Gabriel 特别呼吁社区用户在大规模环境中测试 estimate 模式：</p><ul><li>当前测试环境约 400 万对象（规模偏小）</li><li>希望收集 <strong>10 亿级对象</strong>场景的测试反馈</li><li>希望了解在复杂 IAM 权限策略（production policy）下的表现</li><li>欢迎反馈 bucket 数量超过 10 万级别的测试结果</li></ul>`,56)])])}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
